NODE_COLORS=["red", "green", "blue", "yellow","cyan", "lightblue", "magenta", "orange", "slategray", "plum", "sienna", "darkorange", "yellowgreen", "pink", "springgreen", "peru", "gold", "teal" ]
def draw_graph_ensemble(ens, bary=False ):

    fig, axes = plt.subplots(1, len(ens), figsize=(15, 5))
    for i, en in enumerate(ens):
    
        ax = axes[i]
        # pos=nx.kamada_kawai_layout(en)
        pos = nx.spring_layout(en)
        cmap=[]
        for node in en:
            if i+1 == len(ens) and bary:
                cmap.append("lightblue")
            else:
                cmap.append(NODE_COLORS[node])
        nx.draw(en, pos=pos, ax=ax, with_labels=True, node_color=cmap, node_size=500)
        # nx.draw(en, pos=pos, ax=ax, with_labels=True, cmap='viridis', node_size=500)
        # nx.draw_networkx_edge_labels(G, pos=nx.spring_layout(G), edge_labels=nx.get_edge_attributes(G,"weight"))
                
        if i+1 == len(ens) and bary:
            ax.set_title("barycenter")
        else:
            ax.set_title(f"G{i}")

    plt.tight_layout()
    plt.show()


def save_graph_ensemble(ens, poses, layout="DL4GD"):
    fig, axes = plt.subplots(1, len(ens), figsize=(15, 5))
    for i, en in enumerate(ens):
        numnodes = en.numberOfNodes()
        filename = f"hi{i}"
        ax = axes[i]
        if layout == 'kamada_kawai':
            pos=nx.kamada_kawai_layout(en)
        elif layout == 'spring':
            pos = nx.spring_layout(en)
        elif layout == 'DL4GD':
            pos = poses[i]
        cmap=NODE_COLORS[:numnodes]
        
        nx.draw(en, pos=pos, ax=ax, with_labels=True, node_color=cmap, node_size=500)
        # nx.draw(en, pos=pos, ax=ax, with_labels=True, cmap='viridis', node_size=500)
        # nx.draw_networkx_edge_labels(G, pos=nx.spring_layout(G), edge_labels=nx.get_edge_attributes(G,"weight"))
        ax.set_title(f"Title{i}")
        ax.savefig(filename)
        ax.close()


    plt.tight_layout()
    plt.show()


